const express = require('express');
const request = require('supertest');
const db = require('./db'); // Mocked db module

const app = express();
app.use(express.json());

app.post('/login', (req, res) => {
  const username = req.body.username;
  const password = req.body.password;
  const query = `SELECT * FROM users WHERE username = '${username}' AND password = '${password}'`;

  db.query(query, (err, results) => {
    if (err) throw err;
    if (results.length > 0) {
      res.json({ success: true, user: results[0] });
    } else {
      res.status(401).json({ success: false });
    }
  });
});

jest.mock('./db'); // Mocking the db module

describe('Login Route', () => {
  it('should return success for valid username and password', async () => {
    const mockResult = [{ id: 1, username: 'testuser', password: 'testpass' }];
    db.query.mockImplementation((query, callback) => callback(null, mockResult));

    const response = await request(app)
      .post('/login')
      .send({ username: 'testuser', password: 'testpass' });

    expect(response.status).toBe(200);
    expect(response.body.success).toBe(true);
    expect(response.body.user).toEqual(mockResult[0]);
  });

  it('should return 401 for invalid username or password', async () => {
    db.query.mockImplementation((query, callback) => callback(null, []));

    const response = await request(app)
      .post('/login')
      .send({ username: 'wronguser', password: 'wrongpass' });

    expect(response.status).toBe(401);
    expect(response.body.success).toBe(false);
  });

  it('should handle SQL injection payloads', async () => {
    const sqlInjection = "' OR '1'='1";
    db.query.mockImplementation((query, callback) => callback(null, []));

    const response = await request(app)
      .post('/login')
      .send({ username: sqlInjection, password: sqlInjection });

    expect(response.status).toBe(401);
    expect(response.body.success).toBe(false);
  });

  it('should handle oversized input', async () => {
    const oversizedInput = 'a'.repeat(10001);
    db.query.mockImplementation((query, callback) => callback(null, []));

    const response = await request(app)
      .post('/login')
      .send({ username: oversizedInput, password: oversizedInput });

    expect(response.status).toBe(401);
    expect(response.body.success).toBe(false);
  });

  it('should handle path traversal strings', async () => {
    const pathTraversal = '../../../etc/passwd';
    db.query.mockImplementation((query, callback) => callback(null, []));

    const response = await request(app)
      .post('/login')
      .send({ username: pathTraversal, password: pathTraversal });

    expect(response.status).toBe(401);
    expect(response.body.success).toBe(false);
  });

  it('should handle integer boundary values', async () => {
    db.query.mockImplementation((query, callback) => callback(null, []));

    const responseZero = await request(app)
      .post('/login')
      .send({ username: 0, password: 0 });
    expect(responseZero.status).toBe(401);
    expect(responseZero.body.success).toBe(false);

    const responseNegative = await request(app)
      .post('/login')
      .send({ username: -1, password: -1 });
    expect(responseNegative.status).toBe(401);
    expect(responseNegative.body.success).toBe(false);

    const maxInt = Number.MAX_SAFE_INTEGER;
    const responseMaxInt = await request(app)
      .post('/login')
      .send({ username: maxInt, password: maxInt });
    expect(responseMaxInt.status).toBe(401);
    expect(responseMaxInt.body.success).toBe(false);
  });
});

