    const response = await request(app).get('/test');
    expect(response.status).toBe(200);
    expect(response.text).toBe('Server running on port 3000');
  });

  test('should handle SQL injection attacks', async () => {
    const sqlInjectionPayload = "' OR '1'='1";
    const response = await request(app).get(`/test?param=${sqlInjectionPayload}`);
    expect(response.status).toBe(200);
    expect(response.text).toBe('Server running on port 3000');
  });

  test('should handle path traversal attempts', async () => {
    const pathTraversalPayload = '../../etc/passwd';
    const response = await request(app).get(`/test?file=${pathTraversalPayload}`);
    expect(response.status).toBe(200);
    expect(response.text).toBe('Server running on port 3000');
  });

  test('should handle oversized input', async () => {
    const oversizedInput = 'A'.repeat(10000);
    const response = await request(app).get(`/test?param=${oversizedInput}`);
    expect(response.status).toBe(200);
    expect(response.text).toBe('Server running on port 3000');
  });

  test('should handle null input', async () => {
    const response = await request(app).get('/test?param=null');
    expect(response.status).toBe(200);
    expect(response.text).toBe('Server running on port 3000');
  });

  test('should handle boundary integer values', async () => {
    const intBoundaryTest = async (value) => {
      const response = await request(app).get(`/test?number=${value}`);
      expect(response.status).toBe(200);
      expect(response.text).toBe('Server running on port 3000');
    };
    await intBoundaryTest(0);
    await intBoundaryTest(-1);
    await intBoundaryTest(Number.MAX_SAFE_INTEGER);
  });
});

