describe('processOrder', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should update order status and return order details for valid inputs', async () => {
    const orderId = 1;
    const status = 'shipped';
    const mockOrder = [{ id: 1, status: 'shipped' }];

    prisma.$transaction.mockImplementation(async (callback) => await callback({
      $executeRawUnsafe: prisma.$executeRawUnsafe,
      $queryRawUnsafe: prisma.$queryRawUnsafe,
    }));
    prisma.$executeRawUnsafe.mockResolvedValueOnce(null);
    prisma.$queryRawUnsafe.mockResolvedValueOnce(mockOrder);

    const result = await processOrder(orderId, status);
    expect(result).toEqual(mockOrder);
    expect(prisma.$executeRawUnsafe).toHaveBeenCalledWith(`UPDATE orders SET status = 'shipped' WHERE id = 1`);
    expect(prisma.$queryRawUnsafe).toHaveBeenCalledWith(`SELECT * FROM orders WHERE id = 1`);
  });

  it('should handle SQL injection attempts in status', async () => {
    const orderId = 1;
    const status = "'); DROP TABLE orders; --";
    prisma.$transaction.mockImplementation(async (callback) => await callback({
      $executeRawUnsafe: prisma.$executeRawUnsafe,
      $queryRawUnsafe: prisma.$queryRawUnsafe,
    }));
    prisma.$executeRawUnsafe.mockResolvedValueOnce(null);

    await expect(processOrder(orderId, status)).rejects.toThrow();
    expect(prisma.$executeRawUnsafe).toHaveBeenCalledWith(`UPDATE orders SET status = '\'); DROP TABLE orders; --' WHERE id = 1`);
  });

